<?php
class AdminController {
 public function index():void {Security::role(['superadmin']);$companies=db_all('SELECT c.*,COUNT(DISTINCT u.id) users FROM companies c LEFT JOIN users u ON u.company_id=c.id GROUP BY c.id ORDER BY c.id DESC');$payments=db_all('SELECT t.*,c.name company,p.name plan_name FROM payment_transactions t JOIN companies c ON c.id=t.company_id LEFT JOIN subscriptions s ON s.id=t.subscription_id LEFT JOIN plans p ON p.id=s.plan_id ORDER BY t.id DESC LIMIT 50');$stats=['companies'=>db_one('SELECT COUNT(*) n FROM companies')['n']??0,'users'=>db_one('SELECT COUNT(*) n FROM users')['n']??0,'pending'=>db_one('SELECT COUNT(*) n FROM payment_transactions WHERE status="pending"')['n']??0];View::render('admin/index',compact('companies','payments','stats'));}
 public function confirmPayment():void {Security::role(['superadmin']);verify_csrf();$id=(int)($_POST['id']??0);$tx=db_one('SELECT * FROM payment_transactions WHERE id=? AND status="pending"',[$id]);if(!$tx){flash('error','Transaction introuvable ou déjà traitée.');redirect('/admin');}$pdo=Database::p();$pdo->beginTransaction();try{$pdo->prepare('UPDATE payment_transactions SET status="paid",paid_at=NOW() WHERE id=?')->execute([$id]);if($tx['subscription_id'])$pdo->prepare('UPDATE subscriptions SET status="active",starts_at=NOW(),ends_at=DATE_ADD(NOW(),INTERVAL IF(billing_cycle="yearly",1,0) YEAR) WHERE id=?')->execute([$tx['subscription_id']]);$pdo->commit();Security::audit('payment.confirmed','payment',$id);flash('success','Paiement confirmé.');}catch(Throwable $e){$pdo->rollBack();flash('error','Confirmation impossible.');}redirect('/admin');}
}
